const cleanHelpKey=v=>String(v??'').replace(/\s+/g,' ').trim();
// Keep the tooltip outside the trigger: only the visible circle can receive pointer events.
let activeHelp=null,helpPinned=false;
const helpBubble=document.createElement('div');helpBubble.className='help-bubble';helpBubble.id='context-help-bubble';helpBubble.setAttribute('role','tooltip');helpBubble.hidden=true;document.body.append(helpBubble);
function hideHelp(){if(activeHelp){activeHelp.removeAttribute('aria-describedby');activeHelp.setAttribute('aria-expanded','false')}activeHelp=null;helpPinned=false;helpBubble.hidden=true;}
function positionHelp(){if(!activeHelp?.isConnected){hideHelp();return}const r=activeHelp.getBoundingClientRect(),margin=10;if(r.bottom<0||r.top>innerHeight||r.right<0||r.left>innerWidth){hideHelp();return}const w=helpBubble.offsetWidth,h=helpBubble.offsetHeight;helpBubble.style.left=Math.max(margin,Math.min(innerWidth-w-margin,r.left+r.width/2-w/2))+'px';helpBubble.style.top=(r.bottom+8+h<=innerHeight-margin?r.bottom+8:Math.max(margin,r.top-h-8))+'px';}
function showHelp(b,pin=false){if(activeHelp!==b){hideHelp();activeHelp=b}helpPinned=pin||helpPinned;helpBubble.textContent=b.dataset.helpTip;helpBubble.hidden=false;b.setAttribute('aria-describedby',helpBubble.id);b.setAttribute('aria-expanded','true');positionHelp()}
function makeHelpDot(tip,title){const b=document.createElement('button');b.type='button';b.className='help-dot';b.setAttribute('aria-label','Spiegazione: '+title);b.setAttribute('aria-expanded','false');b.dataset.helpTip=tip;b.textContent='?';b.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')showHelp(b)});b.addEventListener('pointerleave',()=>{if(activeHelp===b&&!helpPinned&&document.activeElement!==b)hideHelp()});b.addEventListener('focus',()=>showHelp(b));b.addEventListener('blur',()=>{if(activeHelp===b)hideHelp()});b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(activeHelp===b&&helpPinned)hideHelp();else showHelp(b,true)});return b}
document.addEventListener('pointerdown',e=>{if(activeHelp&&!activeHelp.contains(e.target))hideHelp()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeHelp){hideHelp();e.stopPropagation()}},true);window.addEventListener('resize',()=>{if(activeHelp)positionHelp()});document.addEventListener('scroll',()=>{if(activeHelp)positionHelp()},true);
function attachContextHelp(scope,currentPage){
 hideHelp();
 const attach=(el,tip,title)=>{if(!el||!tip)return;el.append(makeHelpDot(tip,title));};
 const title=scope.querySelector('.app-header h1');if(title)attach(title,pageHelp[cleanHelpKey(currentPage)],currentPage);
 scope.querySelectorAll('.panel h2').forEach(el=>{const t=cleanHelpKey(el.textContent);attach(el,titleHelp[t],t)});
 scope.querySelectorAll('label').forEach(label=>{const nodes=[...label.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()),t=cleanHelpKey(nodes.map(n=>n.textContent).join(' ')),tip=t==='Tipo'&&label.querySelector('[name=preset]')?'Scegli una sfida personalizzata oppure la sfida delle 52 settimane, da 1 a 52 euro.':labelHelp[t];if(!tip||!label.querySelector('input,select,textarea'))return;const wrap=document.createElement('div');wrap.className='help-field';const caption=document.createElement('span');caption.className='help-field-caption';caption.textContent=t;nodes[0].replaceWith(caption);nodes.slice(1).forEach(n=>n.remove());label.before(wrap);wrap.append(label,makeHelpDot(tip,t));});
}


