function bind(id,fn){let el=document.getElementById(id);if(el)el.onsubmit=async e=>{e.preventDefault();let b=el.querySelector('button:not([type=button])');b.disabled=true;try{await fn(Object.fromEntries(new FormData(el)))}catch(err){let error=document.querySelector('#error');if(error)error.textContent=err.message;else alert(err.message)}finally{b.disabled=false}}}
let privateTimer=null;
function touchPrivate(){if(!session?.private)return;clearTimeout(privateTimer);privateTimer=setTimeout(lockPrivate,180000);}
function lockPrivate(){const target=session;if(!target?.private)return;clearTimeout(privateTimer);privateTimer=null;for(const el of document.querySelectorAll('dialog')){el.close();el.replaceChildren();el.remove();}hideHelp();helpBubble.textContent='';document.onkeydown=null;root.replaceChildren();session=target.parent;({page,month,projectTab}=target.returnView);target.key=null;target.data=null;target.view=null;target.parent=null;render();window.scrollTo(0,0);}
for(const event of ['pointerdown','keydown','input','scroll'])document.addEventListener(event,touchPrivate,{passive:true,capture:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)lockPrivate()});
async function enterPrivate(parent,opened,envelope){await queue;if(session!==parent||parent.data.privateEnvelope!==envelope||document.hidden)return;const data=validateOverlay(parent.data,validateState(upgradePrivateWorkspace(opened.data,parent.data.theme)));session={id:'Privato',private:true,parent,key:opened.key,data,envelope,returnView:{page,month,projectTab}};page='Dashboard';month=d.today().slice(0,7);projectTab='Desideri';render();touchPrivate();window.scrollTo(0,0);}
function changeFor(target,action,fn){const task=queue.then(async()=>{if(session!==target)throw Error('Sessione non attiva');const state=target.data,old=structuredClone(state);try{fn(state);state.audit.push({date:new Date().toISOString(),action});validateState(state);if(target.private){const parent=target.parent,key=target.key;validateOverlay(parent.data,state);const updated=await savePrivateWorkspace(parent,target.envelope,key,state);target.envelope=updated;}else if(!target.demo)await store.save(target);if(session===target)render()}catch(e){if(session===target)target.data=old;throw e}});queue=task.catch(()=>{});return task}
function change(action,fn){return changeFor(session,action,fn)}
function downloadFile(name,content,type='application/json'){let u=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const catColors=['#176b57','#3963cc','#ca8540','#8864b7','#3b9b9b','#d16d87','#7789a6','#bc9c37','#4e9a66','#9295a2'];
function dashboard(s,f){
 const months=Array.from({length:6},(_,i)=>{const a=new Date(+month.slice(0,4),+month.slice(5)-1-5+i,1);const k=a.getFullYear()+'-'+String(a.getMonth()+1).padStart(2,'0');return [k,d.flows(s,k+'-01',k+'-31')]});
 const max=Math.max(1,...months.flatMap(([k,x])=>[x.income,x.out]));const vals={'Patrimonio netto':m(d.worth(s)),'Liquidità':m(s.accounts.filter(a=>!a.archived&&a.type!=='Broker').reduce((n,a)=>n+d.balance(s,a),0)),'Entrate':m(f.income),'Uscite':m(f.out),'Risparmio':m(f.net),'Tasso di risparmio':f.rate==null?'N/D':(f.rate*100).toFixed(1).replace('.',',')+'%','Saldi conti':m(s.accounts.reduce((n,a)=>n+d.balance(s,a),0)),'Costi finanziari':m(f.cost),'Trasferimenti':m(f.transfer),'Da classificare':f.unclassified,'Investimenti netti':m(f.buy-f.sell),'Debiti':m(s.liabilities.reduce((n,a)=>n+a.amount,0))};
 const chosen=new Set(s.widgets), order=['Entrate','Uscite','Risparmio','Liquidità','Tasso di risparmio','Saldi conti','Costi finanziari','Trasferimenti','Da classificare','Investimenti netti','Debiti'];let html=order.filter(w=>chosen.has(w)).map(w=>metric(w,vals[w])).join('');
 if(chosen.has('Andamento saldi')||!s.pro?.widgetExtended)html+=pro.trend(s);
 if(chosen.has('Flussi mensili'))html+=panel('Flussi di cassa',`<div class="chart-sub"><span>Ultimi sei mesi</span><div class="chart-legend"><span>Entrate</span><span>Uscite nette</span></div></div><div class="cash-chart"><div class="axis-labels">${[1,.75,.5,.25,0].map(p=>`<span>${m(Math.round(max*p)).replace(',00','')}</span>`).join('')}</div><div class="chart">${months.map(([k,x])=>`<div class="month"><div class="bars"><i title="Entrate: ${m(x.income)}" style="height:${Math.max(0,x.income/max*160)}px"></i><i title="Uscite nette: ${m(x.out)}" style="height:${Math.max(0,x.out/max*160)}px"></i></div><small>${new Date(k+'-15T12:00:00').toLocaleDateString('it-IT',{month:'short'})}</small></div>`).join('')}</div></div>${months.some(([k,x])=>x.out<0)?'<small>Le uscite nette negative (rimborsi) non sono rappresentate dalle barre.</small>':''}`,'chart-wide');
 if(chosen.has('Spese per categoria')){let rows=cats.map((c,i)=>({c,i,v:Math.max(0,d.budgetSpent(s,{category:c},month))})).filter(r=>r.v>0).sort((a,b)=>b.v-a.v);let total=rows.reduce((a,r)=>a+r.v,0),pos=0;let seg=rows.map(r=>{let a=pos;pos+=r.v/total*100;return catColors[r.i]+' '+a+'% '+pos+'%'}).join(',');html+=panel('Spese per categoria',total?`<div class="donut" style="background:conic-gradient(${seg})"><div><small>Spese classificate</small><b>${m(total)}</b></div></div><div class="category-list">${rows.map(r=>`<div><i style="background:${catColors[r.i]}"></i><span>${esc(r.c)}</span><b>${m(r.v)}</b></div>`).join('')}</div>`:`<div class="donut empty"><div><small>Spese classificate</small><b>${m(0)}</b></div></div><p class="muted">Nessuna spesa classificata nel periodo.</p>`,'chart-narrow')}
 if(chosen.has('Ultimi movimenti'))html+=panel('Movimenti recenti',txTable([...s.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))+`<button class="secondary panel-link" data-page="Movimenti">Tutti i movimenti →</button>`);
 for(const w of ['Budget','Obiettivi','Prossime scadenze'])if(chosen.has(w)){const rows=w==='Budget'?s.budgets.map(b=>`<div class="stat-row"><span>${esc(b.category)}</span><b>${m(d.budgetSpent(s,b,month))} / ${m(b.amount)}</b></div>${progress(d.budgetSpent(s,b,month),b.amount)}`):w==='Obiettivi'?s.goals.map(g=>`<div class="stat-row"><span>${esc(g.name)}</span><b>${m(g.saved)} / ${m(g.amount)}</b></div>${progress(g.saved,g.amount)}`):s.recurring.map(r=>`<div class="stat-row"><span>${esc(r.name)}<small>${esc(r.date)}</small></span><b>${m(r.amount)}</b></div>`);html+=panel(w,rows.join('')||'<p class="muted empty-state">Nessun elemento registrato.</p>','wide')}
 return html;
}
